#!/usr/bin/env node
// Compile the legacy SPA root in-DOM template (#app) into a static render
// function so browsers no longer need Vue's runtime template compiler for the
// 176KB root template. The generated file is committed; production never runs
// Node. Run `npm install` once, then `npm run build` after changing index.html.
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { compile, parse } from '@vue/compiler-dom'

const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, '../..')
const indexFile = path.join(repo, 'web/static/legacy/index.html')
const outFile = path.join(repo, 'web/static/legacy/app.render.js')
const vueRuntime = path.join(repo, 'web/static/legacy/lib/vue.global.prod.js')
const compilerVersion = JSON.parse(fs.readFileSync(path.join(here, 'node_modules/@vue/compiler-dom/package.json'), 'utf8')).version

function findApp (node, out = []) {
  if (!node || typeof node !== 'object') return out
  if (node.type === 1 && Array.isArray(node.props)) {
    const id = node.props.find(p => p.type === 6 && p.name === 'id')
    if (id && id.value && id.value.content === 'app') out.push(node)
  }
  if (Array.isArray(node.children)) for (const child of node.children) findApp(child, out)
  return out
}

function build () {
  const html = fs.readFileSync(indexFile, 'utf8')
  const matches = findApp(parse(html, { comments: true }))
  if (matches.length !== 1) throw new Error(`expected exactly one #app container, found ${matches.length}`)
  const app = matches[0]
  const kids = app.children.filter(Boolean)
  if (!kids.length) throw new Error('#app is empty')
  const template = html.slice(kids[0].loc.start.offset, kids[kids.length - 1].loc.end.offset)

  const result = compile(template, {
    mode: 'module',
    prefixIdentifiers: true,
    hoistStatic: true,
    cacheHandlers: true,
    comments: false,
  })
  let code = result.code
  const importMatch = code.match(/^import \{([\s\S]*?)\} from "vue"\s*/m)
  if (!importMatch) throw new Error('compiler output has no vue import to rewrite')
  const bindings = importMatch[1].replace(/\s+/g, ' ').replace(/ as /g, ': ').trim()
  code = code.replace(importMatch[0], `const { ${bindings} } = Vue;\n`)
  code = code.replace(/export function render\(/, 'function render(')
  if (/^\s*(import|export)\s/m.test(code)) throw new Error('compiler output still contains ESM syntax')

  const templateHash = createHash('sha256').update(template).digest('hex')
  const templateBytes = Buffer.byteLength(template)
  const header = `/* generated by tools/spa_precompile/precompile.mjs; vue=${compilerVersion} template-sha256=${templateHash} template-size=${templateBytes} */\n`
  // runtime-only Vue（没有模板编译器）：运行库缺失时直接返回，不抛异常。
  // 否则 abort/损坏 vue.global.prod.js 会先在渲染产物里抛 ReferenceError（pageerror），
  // app.js 的可见错误页就再也走不到了。
  const body = `${header}(function () {\n'use strict';\n`
    + `if (typeof Vue === 'undefined' || !Vue) {\n`
    + `  try { console.error('[yxq] app.render.js skipped: Vue runtime missing'); } catch (e) {}\n`
    + `  return;\n}\n`
    + `${code}\nwindow.__YXQ_RENDER__ = render;\n})();\n`
  return { body, templateHash, templateBytes, codeBytes: Buffer.byteLength(body) }
}

const { body, templateHash, templateBytes, codeBytes } = build()
const gz = (await import('node:zlib')).gzipSync(body, { level: 6 }).length

if (process.argv.includes('--check')) {
  if (!fs.existsSync(outFile)) {
    console.error('app.render.js is missing; run: cd tools/spa_precompile && npm run build')
    process.exit(1)
  }
  const current = fs.readFileSync(outFile, 'utf8')
  if (current !== body) {
    console.error('app.render.js is stale: regenerate with `cd tools/spa_precompile && npm run build`')
    process.exit(1)
  }
  console.log(`app.render.js OK (template ${templateBytes}B, render ${codeBytes}B, gzip ${gz}B, sha ${templateHash.slice(0, 12)})`)
  process.exit(0)
}

fs.writeFileSync(outFile, body)
console.log(`wrote ${path.relative(repo, outFile)}: template ${templateBytes}B -> render ${codeBytes}B (gzip ${gz}B), vue ${compilerVersion}, sha ${templateHash.slice(0, 12)}`)
